		{
			this.ActualSize = -1L;
			this.MinSize = -1L;
			this.Hash = null;
			this.CanUseExistsFile = true;
			this.IsJson = false;
			this.ActualSize = ActualSize;
			this.MinSize = MinSize;
			this.Hash = Hash;
			this.CanUseExistsFile = CanUseExistsFile;
			this.IsJson = IsJson;
		}

		public string Check(string LocalPath)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Expected O, but got Unknown
			string result;
			try
			{
				Log($"[Checker] 开始校验文件 {LocalPath}", LogLevel.Developer);
				FileInfo val = new FileInfo(LocalPath);
				if (!val.Exists)
				{
					result = "文件不存在：" + LocalPath;
				}
				else
				{
					long length = val.Length;
					List<string> val2 = new List<string>();
					bool flag = false;
					if (!string.IsNullOrEmpty(Hash))
					{
						if (Hash.Length < 35)
						{
							string fileMD = GetFileMD5(LocalPath);
							if (Operators.CompareString(Hash.ToLowerInvariant(), fileMD, false) != 0)
							{
								val2.Add("文件 MD5 应为 " + Hash + "，实际为 " + fileMD);
							}
						}
						else if (Hash.Length == 64)
						{
							string fileSHA = GetFileSHA256(LocalPath);
							if (Operators.CompareString(Hash.ToLowerInvariant(), fileSHA, false) != 0)
							{
								val2.Add("文件 SHA256 应为 " + Hash + "，实际为 " + fileSHA);
							}
						}
						else
						{
							string fileSHA2 = GetFileSHA1(LocalPath);
							if (Operators.CompareString(Hash.ToLowerInvariant(), fileSHA2, false) != 0)
							{
								val2.Add("文件 SHA1 应为 " + Hash + "，实际为 " + fileSHA2);
							}
						}
						flag = val2.Count == 0;
					}
					if (ActualSize >= 0 && ActualSize != length && !flag)
					{
						val2.Add($"文件大小应为 {ActualSize} B，实际为 {length} B" + ((length < 2000) ? ("，内容为" + ReadFile(LocalPath)) : ""));
					}
					if (MinSize >= 0 && MinSize > length)
					{
						val2.Add($"文件大小应大于 {MinSize} B，实际为 {length} B" + ((length < 2000) ? ("，内容为：" + ReadFile(LocalPath)) : ""));
					}
					if (IsJson)
					{
						string text = ReadFile(LocalPath);
						if (Operators.CompareString(text, "", false) == 0)
						{
							throw new System.Exception("读取到的文件为空");
						}
						try
						{
							GetJson(text);
						}
						catch (System.Exception ex)
						{
							ProjectData.SetProjectError(ex);
							System.Exception ex2 = ex;
							throw new System.Exception("不是有效的 Json 文件", ex2);
						}
					}
					if (val2.Count != 0)
					{
						val2.Insert(0, $"实际校验地址：{LocalPath}");
						result = Join((System.Collections.IEnumerable)val2, ";");
					}
					else
					{
						result = null;
					}
				}
			}
			catch (System.Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				System.Exception ex4 = ex3;
				Log(ex4, "检查文件出错");
				result = ex4.ToString();
				ProjectData.ClearProjectError();
			}
			return result;
		}
	}

