	public static string GetPathFromFullPath(string FilePath)
	{
		if (!FilePath.Contains("\\") && !FilePath.Contains("/"))
		{
			throw new System.Exception("不包含路径：" + FilePath);
		}
		checked
		{
			string text;
			if (EndsWithF(FilePath, "\\") || EndsWithF(FilePath, "/"))
			{
				bool flag = EndsWithF(FilePath, "\\");
				FilePath = Strings.Left(FilePath, Strings.Len(FilePath) - 1);
				text = Strings.Left(FilePath, FilePath.LastIndexOfAny(new char[] { '\\', '/' })) + (flag ? "\\" : "/");
			}
			else
			{
				text = Strings.Left(FilePath, FilePath.LastIndexOfAny(new char[] { '\\', '/' }) + 1);
				if (Operators.CompareString(text, "", false) == 0)
				{
					throw new System.Exception("不包含路径：" + FilePath);
				}
			}
			return text;
		}
	}

	public static string GetFileNameFromPath(string FilePath)
	{
		//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
		FilePath = FilePath.Replace("/", "\\");
		if (EndsWithF(FilePath, "\\"))
		{
			throw new System.Exception("不包含文件名：" + FilePath);
		}
		if (FilePath.Contains("?"))
		{
			FilePath = FilePath.Substring(0, IndexOfF(FilePath, "?"));
		}
		if (FilePath.Contains("\\"))
		{
			FilePath = FilePath.Substring(checked(LastIndexOfF(FilePath, "\\") + 1));
		}
		int length = FilePath.Length;
		if (length == 0)
		{
			throw new System.Exception("不包含文件名：" + FilePath);
		}
		if (length > 250)
		{
			throw new PathTooLongException("文件名过长：" + FilePath);
		}
		return FilePath;
	}

