			}
			for (int j = mid + 1; j <= right; j++)
			{
				val2.Add(array[j]);
			}
			int num = 0;
			int num2 = 0;
			int num3 = left;
			while (num < val.Count && num2 < val2.Count)
			{
				if (comparator(val[num], val2[num2]))
				{
					array[num3] = val[num];
					num++;
				}
				else
				{
					array[num3] = val2[num2];
					num2++;
				}
				num3++;
			}
			while (num < val.Count)
			{
				array[num3] = val[num];
				num++;
				num3++;
			}
			while (num2 < val2.Count)
