	public static bool CheckPermission(string Path)
	{
		bool result;
		try
		{
			if (string.IsNullOrEmpty(Path))
			{
				result = false;
			}
			else
			{
				if (!EndsWithF(Path, "\\"))
				{
					Path += "\\";
				}
				if (EndsWithF(Path, ":\\System Volume Information\\") || EndsWithF(Path, ":\\$RECYCLE.BIN\\"))
				{
					result = false;
				}
				else if (!Directory.Exists(Path))
				{
					result = false;
				}
				else
				{
					string text = "CheckPermission" + Conversions.ToString(GetUuid());
					if (File.Exists(Path + text))
					{
						File.Delete(Path + text);
					}
					((Stream)File.Create(Path + text)).Dispose();
					File.Delete(Path + text);
					result = true;
				}
			}
		}
		catch (System.Exception ex)
		{
			ProjectData.SetProjectError(ex);
			System.Exception ex2 = ex;
			Log(ex2, "没有对文件夹 " + Path + " 的权限，请尝试以管理员权限运行 PCL");
			result = false;
			ProjectData.ClearProjectError();
		}
		return result;
	}

	public static void CheckPermissionWithException(string Path)
	{
		//IL_000d: Unknown result type (might be due to invalid IL or missing references)
		//IL_003b: Unknown result type (might be due to invalid IL or missing references)
		if (string.IsNullOrWhiteSpace(Path))
		{
			throw new ArgumentNullException("文件夹名不能为空！");
		}
		if (!EndsWithF(Path, "\\"))
		{
			Path += "\\";
		}
		if (!Directory.Exists(Path))
		{
			throw new DirectoryNotFoundException("文件夹不存在！");
		}
		if (File.Exists(Path + "CheckPermission"))
		{
			File.Delete(Path + "CheckPermission");
		}
		((Stream)File.Create(Path + "CheckPermission")).Dispose();
		File.Delete(Path + "CheckPermission");
	}

