			ModMain.Hint(Text, ModMain.HintType.Critical, Log: false);
			break;
		case LogLevel.Msgbox:
			ModMain.MyMsgBox(Text, Title, "确定", "", "", IsWarn: true);
			break;
		case LogLevel.Feedback:
			if (CanFeedback(ShowHint: false))
			{
				if (ModMain.MyMsgBox(Text + "\r\n\r\n是否反馈此问题？如果不反馈，这个问题可能永远无法得到解决！", Title, "反馈", "取消", "", IsWarn: true) == 1)
