				}
			}
			else
			{
				ModMain.MyMsgBox(Text + "\r\n\r\n将 PCL 更新至最新版或许可以解决这个问题……", Title, "确定", "", "", IsWarn: true);
			}
			break;
		case LogLevel.Critical:
			if (IsCriticalErrorTriggered)
			{
				FormMain.EndProgramForce(ProcessReturnValues.Exception);
				break;
			}
			IsCriticalErrorTriggered = true;
			if (CanFeedback(ShowHint: false))
			{
				if ((int)Interaction.MsgBox((object)(Text + "\r\n\r\n是否反馈此问题？如果不反馈，这个问题可能永远无法得到解决！"), (MsgBoxStyle)20, (object)Title) == 6)
				{
					Feedback(ShowMsgbox: false, ForceOpenLog: true);
				}
			}
			else
			{
				Interaction.MsgBox((object)(Text + "\r\n\r\n将 PCL 更新至最新版或许可以解决这个问题……"), (MsgBoxStyle)16, (object)Title);
			}
			break;
		case LogLevel.Developer:
			break;
		}
	}

