	public static void DebugAssert(bool Exp)
	{
		if (!Exp)
		{
			throw new System.Exception("断言命中");
		}
	}

	public static string GetStackTrace()
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		return Join((System.Collections.IEnumerable)Enumerable.ToList<string>(Enumerable.Select<MethodBase, string>(Enumerable.Select<StackFrame, MethodBase>(Enumerable.Skip<StackFrame>((System.Collections.Generic.IEnumerable<StackFrame>)new StackTrace().GetFrames(), 1), (Func<StackFrame, MethodBase>)([SpecialName] (StackFrame f) => f.GetMethod())), (Func<MethodBase, string>)([SpecialName] (MethodBase f) => string.Concat(new string[5]
		{
			((MemberInfo)f).Name,
			"(",
			Join((System.Collections.IEnumerable)Enumerable.ToList<string>(Enumerable.Select<ParameterInfo, string>((System.Collections.Generic.IEnumerable<ParameterInfo>)f.GetParameters(), (Func<ParameterInfo, string>)([SpecialName] (ParameterInfo p) => p.ToString()))), ", "),
			") - ",
			((MemberInfo)f).Module.ToString()
		})))), "\r\n").Replace("\r\n\r\n", "\r\n");
	}
}
